'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE='https://plan-ex.ru/erpv2/',U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P15_OUT||'P15_trip_lifecycle_output'),SHOTS=path.join(OUT,'P15_screenshots');fs.mkdirSync(SHOTS,{recursive:true});
const COMPANY=27,TRIP='P15 UI рейс полный жизненный цикл';
const USERS={OWNER:{id:16,username:'p14_owner_260804221827'},SENIOR_LOGIST:{id:17,username:'p14_senior_260804221827'},LOGIST_1:{id:18,username:'p14_logist1_260804221827'},LOGIST_2:{id:19,username:'p14_logist2_260804221827'}};
function allCreds(){const e=process.env.P15_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function sa(){return allCreds().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function login(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded',timeout:45000});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(450);ok=!/\/login(?:[/?#]|$)/.test(p.url())}catch{}return{c,p,ok}}
function candidates(t,v,username){const a=[...v];for(const m of String(t).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==username&&!x.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(x))}
async function resetAndLogin(b,role){const admin=sa(),s=await login(b,admin.username,admin.password);if(!s.ok)throw Error('superadmin login failed');const meta=USERS[role];await s.p.goto(U(`superadmin/companies/${COMPANY}/users`),{waitUntil:'domcontentloaded'});const action=role==='OWNER'?`/superadmin/companies/${COMPANY}/owner/reset-password`:`/superadmin/companies/${COMPANY}/users/logists/${meta.id}/reset-password`;const f=s.p.locator(`form[action$="${action}"]`).first();if(!(await f.count()))throw Error('reset form unavailable '+role);const n=s.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await n;const vals=await s.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(x=>x.value||x.getAttribute('data-password')||x.textContent||'').filter(Boolean));const list=candidates(await s.p.locator('body').innerText(),vals,meta.username);await s.c.close();for(const q of list){const x=await login(b,meta.username,q);if(x.ok){list.fill('');return x}await x.c.close()}throw Error('role login failed '+role)}
function diag(p,r){p.on('console',m=>{if(m.type()==='error')r.consoleErrors.push(m.text())});p.on('pageerror',e=>r.pageErrors.push(String(e.message||e)));p.on('requestfailed',q=>r.requestFailures.push({method:q.method(),url:q.url(),error:q.failure()?.errorText||''}));p.on('response',z=>{if(z.status()>=400)r.httpFailures.push({status:z.status(),url:z.url()})})}
async function openEdit(p){await p.goto(U('company/trips/linear'),{waitUntil:'networkidle',timeout:45000});const row=p.locator('tr[data-linear-route-id]').filter({hasText:TRIP}).first();await row.waitFor({state:'visible'});const id=Number(await row.getAttribute('data-linear-route-id'));await row.dblclick();const edit=p.locator('[data-linear-trip-edit-btn]').first();await edit.waitFor({state:'visible'});await edit.click();const form=p.locator('#linear-trip-edit-form');await form.waitFor({state:'visible'});return{id,form}}
async function saveEdit(p,form){const responses=[];const h=async z=>{if(/\/company\/trips\/linear\/\d+\/modal-edit/.test(z.url())){let body='';try{body=await z.text()}catch{}responses.push({status:z.status(),body:body.slice(0,3000),url:z.url()})}};p.on('response',h);const btn=p.locator('[data-linear-trip-save-btn]').first();await btn.click();await p.waitForTimeout(1800);p.off('response',h);return responses.at(-1)||null}
const pdf=(label)=>Buffer.from(`%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Count 0>>endobj\n% ${label}\n%%EOF\n`,'utf8');
(async()=>{const r={status:'FAIL',tripId:null,edit:{},documents:{},roles:[],consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[],sqlLeak:false,error:null};let b,owner;try{b=await chromium.launch({headless:true});owner=await resetAndLogin(b,'OWNER');diag(owner.p,r);let opened=await openEdit(owner.p);r.tripId=opened.id;const f=opened.form;await f.locator('[name="planned_unloading_date"]').fill('12.08.2026');await f.locator('[name="actual_loading_date"]').fill('10.08.2026');await f.locator('[name="actual_unloading_date"]').fill('12.08.2026');await f.locator('[name="comments"]').fill('P15 lifecycle PASS: рейс создан, повторно открыт, отредактирован, документы проверены');await f.locator('[name="customer_payments[0][amount]"]').fill('160000');await f.locator('[name="customer_document"]').setInputFiles({name:'P15_договор_заказчик_v1.pdf',mimeType:'application/pdf',buffer:pdf('customer-v1')});await f.locator('[name="carrier_document"]').setInputFiles({name:'P15_заявка_перевозчик.pdf',mimeType:'application/pdf',buffer:pdf('carrier-v1')});await owner.p.screenshot({path:path.join(SHOTS,'P15_007_OWNER_trip_edit_filled_documents_1920x1080.png'),fullPage:false});r.edit.firstSave=await saveEdit(owner.p,f);if(!r.edit.firstSave||r.edit.firstSave.status!==200||!r.edit.firstSave.body.includes('"success":true'))throw Error('first edit save failed');opened=await openEdit(owner.p);await owner.p.locator('[data-linear-trip-cancel-edit-btn]').click();await owner.p.waitForTimeout(300);await owner.p.locator('[data-linear-trip-view-close-btn]').click().catch(()=>{});await owner.p.goto(U('company/trips/linear'),{waitUntil:'networkidle'});const row=owner.p.locator('tr[data-linear-route-id]').filter({hasText:TRIP}).first();await row.dblclick();await owner.p.waitForTimeout(700);const view=owner.p.locator('#linear-trip-view-modal');const text=(await view.innerText()).replace(/\s+/g,' ');r.edit.reopened={updatedAmount:/160\s*000/.test(text),actualDates:text.includes('10.08.2026')&&text.includes('12.08.2026'),comment:text.includes('P15 lifecycle PASS')};const links=await view.locator('a[href*="/company/documents/"]').evaluateAll(ns=>ns.map(n=>({text:(n.innerText||'').trim(),href:n.href,download:n.hasAttribute('download')})));r.documents.links=links;for(const link of links){const resp=await owner.c.request.get(link.href);r.documents[link.download?'download':'view']=(r.documents[link.download?'download':'view']||[]).concat([{status:resp.status(),contentType:resp.headers()['content-type']||'',url:link.href}])}await owner.p.screenshot({path:path.join(SHOTS,'P15_008_OWNER_trip_view_documents_1920x1080.png'),fullPage:false});await owner.p.locator('[data-linear-trip-edit-btn]').click();const replace=owner.p.locator('#linear-trip-edit-form');await replace.waitFor({state:'visible'});await replace.locator('[name="customer_document"]').setInputFiles({name:'P15_договор_заказчик_v2.pdf',mimeType:'application/pdf',buffer:pdf('customer-v2')});r.edit.replaceSave=await saveEdit(owner.p,replace);if(!r.edit.replaceSave||r.edit.replaceSave.status!==200||!r.edit.replaceSave.body.includes('"success":true'))throw Error('replace save failed');await owner.p.goto(U('company/trips/linear'),{waitUntil:'networkidle'});const finalRow=owner.p.locator('tr[data-linear-route-id]').filter({hasText:TRIP}).first();await finalRow.dblclick();await owner.p.waitForTimeout(600);const finalText=await owner.p.locator('#linear-trip-view-modal').innerText();r.documents.replaced=finalText.includes('P15_договор_заказчик_v2.pdf');r.sqlLeak=/SQLSTATE|Integrity constraint|stack trace|payment_due_type/i.test(finalText);await owner.p.screenshot({path:path.join(SHOTS,'P15_009_OWNER_trip_document_replaced_1920x1080.png'),fullPage:false});await owner.c.close();owner=null;
for(const role of ['SENIOR_LOGIST','LOGIST_1','LOGIST_2']){const x=await resetAndLogin(b,role);const p=x.p;const responses=[];p.on('response',z=>{if(z.request().resourceType()==='document')responses.push({status:z.status(),url:z.url()})});await p.goto(U('company/trips/linear'),{waitUntil:'domcontentloaded'});const visible=await p.locator('tr[data-linear-route-id]').filter({hasText:TRIP}).count()>0;r.roles.push({role,finalUrl:p.url(),mainStatus:responses.at(-1)?.status||null,tripVisible:visible,financeMenuVisible:(await p.locator('a[href*="/company/finance/"]:visible').count())>0});await p.screenshot({path:path.join(SHOTS,`P15_010_${role}_trip_visibility_1920x1080.png`),fullPage:false});await x.c.close()}
const docsOk=(r.documents.view||[]).every(x=>x.status===200)&&(r.documents.download||[]).every(x=>x.status===200);r.status=r.tripId>0&&r.edit.firstSave?.status===200&&r.edit.replaceSave?.status===200&&Object.values(r.edit.reopened).every(Boolean)&&r.documents.replaced&&docsOk&&!r.sqlLeak&&r.pageErrors.length===0&&r.requestFailures.length===0?'PASS':'FAIL'}catch(e){r.error={name:e.name||'Error',message:String(e.message||e).slice(0,800)}}finally{if(owner?.c)await owner.c.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P15_TRIP_LIFECYCLE_RUNTIME.json'),JSON.stringify(r,null,2));console.log('P15_TRIP_LIFECYCLE='+r.status);process.exitCode=r.status==='PASS'?0:1}})();
